import csv
from collections import defaultdict
tid='20f10a84-4ec1-54ad-896a-1b534d833709'
per=defaultdict(list)
rows=csv.DictReader(open(VALUES_CSV))
for r in rows:
    if r['timeseries_id']==tid:
        ts=r['timestamp']
        day=ts[:10]
        if day.startswith('2018-04'):
            per[day].append((ts,float(r['value'])))
best=None
for day in sorted(per):
    if len(per[day])==24:
        s=sum(v for _,v in per[day])
        if best is None or s>best[1]:
            best=(day,s)
print(best)
print({d:len(v) for d,v in per.items()})
